import numpy as np, itertools
def readxyz(f):
    lines = open(f).read().splitlines()
    n = int(lines[0].split()[0])
    els, xyz = [], []
    for l in lines[2:2+n]:
        p = l.split()
        els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
    return els, np.array(xyz)
els, xyz = readxyz("xtbopt.xyz")
cov = {'H':0.31,'C':0.76,'N':0.71,'Cl':1.02,'Zr':1.55}
n=len(els)
adj = {i:[] for i in range(n)}
for i,j in itertools.combinations(range(n),2):
    d = np.linalg.norm(xyz[i]-xyz[j])
    if d < cov[els[i]]+cov[els[j]]+0.45:
        adj[i].append(j); adj[j].append(i)
iZr = els.index('Zr')
print("Zr bonded:", [(els[k],k) for k in adj[iZr]])
Ns=[i for i,e in enumerate(els) if e=='N']
for iN in Ns:
    print(f"N{iN} bonded:", [(els[k],k) for k in adj[iN]])
# find metallacycle ring size via BFS between the two N through non-Zr path
import collections
def bfs_path(a,b,avoid):
    q=collections.deque([(a,[a])]); seen={a}
    while q:
        cur,p=q.popleft()
        if cur==b: return p
        for nb in adj[cur]:
            if nb not in seen and nb not in avoid:
                seen.add(nb); q.append((nb,p+[nb]))
    return None
p = bfs_path(Ns[0],Ns[1],{iZr})
print("N..N backbone path:", [(els[k],k) for k in p], "ring size:", len(p)+1)
# methyls on backbone
for k in p[1:-1]:
    nbrs=[(els[q],q) for q in adj[k]]
    print(f"backbone C{k}: {nbrs}")
